const pageSizes=[[1920, 1433], [1920, 1080], [1920, 1645], [1920, 1489], [1920, 1463], [1920, 1333], [1920, 1080], [1920, 1080], [1920, 1080], [1920, 1080], [1920, 1080], [1920, 3988]];
const titles=["传统业务流程与痛点", "AI 机会点", "功能框架", "三个核心模块", "核心模块页面展示", "Agent 对话设计：目标与策略", "语音交互：降低操作成本", "近期拜访：快捷入口", "回复模板：引导完善输入", "双重核实：结果可控", "业务延续：下一步动作", "完整流程与补充展示"];
const outline=document.querySelector('#outline'),pages=document.querySelector('#pages'),reader=document.querySelector('#reader');
outline.innerHTML='<div class="nav-section">设计方案</div>'+titles.map((t,i)=>`<button class="nav-item ${i===0?'active':''}" data-page="${i}"><span>${String(i+1).padStart(2,'0')}</span>${t}</button>`).join('');
pages.innerHTML=titles.map((t,i)=>`<section class="slide" id="slide-${i}" data-index="${i}" aria-label="${t}"><div class="slide-caption"><span>${String(i+1).padStart(2,'0')}</span>${t}</div><button data-zoom="${i}" aria-label="放大查看${t}"><img src="pages/pdf-${String(i+1).padStart(2,'0')}.jpg" width="${pageSizes[i][0]}" height="${pageSizes[i][1]}" alt="${t}设计方案" ${i?'loading="lazy"':'fetchpriority="high"'}></button></section>`).join('');
function go(i){document.querySelector('#slide-'+i).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});document.body.classList.remove('outline-open');syncToc()}
outline.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
let raf;reader.addEventListener('scroll',()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{const top=reader.getBoundingClientRect().top;let active=0;document.querySelectorAll('.slide').forEach((s,i)=>{if(s.getBoundingClientRect().top<top+reader.clientHeight*.32)active=i});document.querySelectorAll('.nav-item').forEach((b,i)=>{b.classList.toggle('active',i===active);if(i===active)b.setAttribute('aria-current','location');else b.removeAttribute('aria-current')});document.querySelector('#pageIndicator').textContent=`${active+1} / ${titles.length}`})});
document.querySelector('#backTop').onclick=()=>go(0);
const tocToggle=document.querySelector('#tocToggle');
function syncToc(){const small=innerWidth<=900;const visible=small?document.body.classList.contains('outline-open'):!document.body.classList.contains('toc-hidden');tocToggle.textContent=visible?'收起目录':'展开目录';tocToggle.setAttribute('aria-expanded',String(visible))}
tocToggle.onclick=()=>{document.body.classList.toggle(innerWidth<=900?'outline-open':'toc-hidden');syncToc()};
addEventListener('resize',syncToc);syncToc();
const toggle=document.querySelector('#demoToggle');function toggleDemo(){if(innerWidth<=700){const on=document.body.classList.toggle('mobile-demo');toggle.textContent=on?'返回方案':'体验原型';toggle.setAttribute('aria-pressed',on)}else{const hidden=document.body.classList.toggle('demo-hidden');toggle.textContent=hidden?'展开原型':'收起原型';toggle.setAttribute('aria-pressed',!hidden)}}toggle.onclick=toggleDemo;if(innerWidth<=700){toggle.textContent='体验原型';toggle.setAttribute('aria-pressed','false')}
const demo=document.querySelector('#demo');demo.addEventListener('load',()=>{try{const s=demo.contentDocument.createElement('style');s.textContent='html,html body,html body.home-refined,html body.detail-route,html body.ai-route,html body.form-route{margin:0!important;padding:0!important;min-width:0!important;width:100%!important;height:100dvh!important;overflow:hidden!important;display:block!important;background:#f4f7fb!important}html body #app,html body.home-refined #app,html body.detail-route #app{margin:0!important;width:100%!important;max-width:none!important;height:100dvh!important;max-height:none!important;min-height:0!important;border:0!important;border-radius:0!important;box-shadow:none!important}';demo.contentDocument.head.append(s)}catch(e){demo.title='原型加载失败，请刷新'}});
document.querySelector('#resetDemo').onclick=()=>demo.contentWindow.location.reload();
pages.onclick=e=>{const b=e.target.closest('[data-zoom]');if(!b)return;const i=Number(b.dataset.zoom);const dialog=document.createElement('dialog');dialog.innerHTML=`<button aria-label="关闭放大图">×</button><div class="lightbox-content"><img src="pages/pdf-${String(i+1).padStart(2,'0')}.jpg" width="${pageSizes[i][0]}" height="${pageSizes[i][1]}" alt="${titles[i]}放大图"></div>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};dialog.onclose=()=>dialog.remove();dialog.showModal()};

addEventListener("resize",()=>{const mobile=innerWidth<=700;toggle.textContent=mobile?(document.body.classList.contains("mobile-demo")?"返回方案":"体验原型"):(document.body.classList.contains("demo-hidden")?"展开原型":"收起原型")});

const chevron=(right)=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${right?'M9 5l7 7-7 7':'M15 5l-7 7 7 7'}"/></svg>`;
function syncEdges(){const small=innerWidth<=900;const toc=small?document.body.classList.contains('outline-open'):!document.body.classList.contains('toc-hidden');const demoOn=innerWidth<=700?document.body.classList.contains('mobile-demo'):!document.body.classList.contains('demo-hidden');tocToggle.innerHTML=chevron(!toc);tocToggle.title=toc?'收起目录':'展开目录';tocToggle.setAttribute('aria-label',tocToggle.title);toggle.innerHTML=chevron(demoOn);toggle.title=demoOn?'收起原型':'展开原型';toggle.setAttribute('aria-label',toggle.title)}
new MutationObserver(syncEdges).observe(document.body,{attributes:true,attributeFilter:['class']});addEventListener('resize',syncEdges);syncEdges();

const prototypePanel=document.querySelector('.prototype');
function fitDevice(){if(!prototypePanel.clientWidth||!prototypePanel.clientHeight)return;const cs=getComputedStyle(prototypePanel);const w=prototypePanel.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight);const h=prototypePanel.clientHeight-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom)-6;const scale=Math.min(1,w/402,h/856);prototypePanel.style.setProperty('--device-scale',String(Math.max(.1,scale)))}
new ResizeObserver(fitDevice).observe(prototypePanel);addEventListener('resize',fitDevice);fitDevice();
